pragma solidity ^0.8.20;
interface IERC20Minimal {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}
interface IERC721Minimal {
    function safeTransferFrom(address from, address to, uint256 tokenId, bytes calldata data) external;
}
interface INonfungiblePositionManager {
    struct MintParams {
        address token0;
        address token1;
        uint24 fee;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }
    function createAndInitializePoolIfNecessary(
        address token0,
        address token1,
        uint24 fee,
        uint160 sqrtPriceX96
    ) external payable returns (address pool);
    function mint(MintParams calldata params)
        external
        payable
        returns (uint256 tokenId, uint128 liquidity, uint256 amount0, uint256 amount1);
    function refundETH() external payable;
}
contract LiquidityLauncherV3 {
    uint24 public constant FEE = 10000;
    int24 public constant TOKEN0_TICK_LOWER = -122000;
    int24 public constant TOKEN0_TICK_UPPER = 0;
    int24 public constant TOKEN1_TICK_LOWER = 0;
    int24 public constant TOKEN1_TICK_UPPER = 122000;
    uint160 public constant SQRT_PRICE_X96_TOKEN0 = 177752490807315064912002657;
    uint160 public constant SQRT_PRICE_X96_TOKEN1 = 35313720257181108417245349150782;
    address public immutable locker;
    address public immutable positionManager;
    address public immutable wrappedNative;
    event LiquidityLaunched(
        address indexed token,
        address indexed user,
        address indexed pool,
        address feeRecipient,
        uint256 tokenId,
        uint128 liquidity,
        bool tokenIsToken0,
        uint256 amount0Used,
        uint256 amount1Used,
        uint256 refunded
    );
    constructor(address locker_, address positionManager_, address wrappedNative_) {
        require(locker_ != address(0), "ZERO_LOCKER");
        require(positionManager_ != address(0), "ZERO_POSITION_MANAGER");
        require(wrappedNative_ != address(0), "ZERO_WRAPPED_NATIVE");
        locker = locker_;
        positionManager = positionManager_;
        wrappedNative = wrappedNative_;
    }
    function launchAndLock(address token, uint256 amount, address feeRecipient)
        external
        payable
        returns (uint256 tokenId, address pool)
    {
        require(token != address(0), "ZERO_TOKEN");
        require(token != wrappedNative, "TOKEN_IS_WRAPPED_NATIVE");
        require(amount > 0, "ZERO_AMOUNT");
        require(feeRecipient != address(0), "ZERO_FEE_RECIPIENT");
        bool tokenIsToken0 = token < wrappedNative;
        address token0;
        address token1;
        uint160 sqrtPriceX96;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        if (tokenIsToken0) {
            token0 = token;
            token1 = wrappedNative;
            sqrtPriceX96 = SQRT_PRICE_X96_TOKEN0;
            tickLower = TOKEN0_TICK_LOWER;
            tickUpper = TOKEN0_TICK_UPPER;
            amount0Desired = amount;
            amount1Desired = msg.value;
        } else {
            token0 = wrappedNative;
            token1 = token;
            sqrtPriceX96 = SQRT_PRICE_X96_TOKEN1;
            tickLower = TOKEN1_TICK_LOWER;
            tickUpper = TOKEN1_TICK_UPPER;
            amount0Desired = msg.value;
            amount1Desired = amount;
        }
        _safeTransferFrom(token, msg.sender, address(this), amount);
        _safeApprove(token, positionManager, amount);
        pool = INonfungiblePositionManager(positionManager)
            .createAndInitializePoolIfNecessary(token0, token1, FEE, sqrtPriceX96);
        uint128 liquidity;
        uint256 amount0Used;
        uint256 amount1Used;
        (tokenId, liquidity, amount0Used, amount1Used) =
            INonfungiblePositionManager(positionManager).mint{value: msg.value}(
                INonfungiblePositionManager.MintParams({
                    token0: token0,
                    token1: token1,
                    fee: FEE,
                    tickLower: tickLower,
                    tickUpper: tickUpper,
                    amount0Desired: amount0Desired,
                    amount1Desired: amount1Desired,
                    amount0Min: 0,
                    amount1Min: 0,
                    recipient: address(this),
                    deadline: block.timestamp + 1200
                })
            );
        require(liquidity > 0, "ZERO_LIQUIDITY");
        if (msg.value > 0) {
            INonfungiblePositionManager(positionManager).refundETH();
            uint256 bnbRefund = address(this).balance;
            if (bnbRefund > 0) {
                (bool refundOk, ) = payable(msg.sender).call{value: bnbRefund}("");
                require(refundOk, "BNB_REFUND_FAILED");
            }
        }
        uint256 leftover = IERC20Minimal(token).balanceOf(address(this));
        if (leftover > 0) {
            _safeTransfer(token, msg.sender, leftover);
        }
        _safeApprove(token, positionManager, 0);
        IERC721Minimal(positionManager).safeTransferFrom(
            address(this),
            locker,
            tokenId,
            abi.encode(feeRecipient)
        );
        emit LiquidityLaunched(
            token,
            msg.sender,
            pool,
            feeRecipient,
            tokenId,
            liquidity,
            tokenIsToken0,
            amount0Used,
            amount1Used,
            leftover
        );
    }
    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        return this.onERC721Received.selector;
    }
    receive() external payable {}
    function _safeTransferFrom(address token, address from, address to, uint256 value) internal {
        (bool ok, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20Minimal.transferFrom.selector, from, to, value)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FROM_FAILED");
    }
    function _safeTransfer(address token, address to, uint256 value) internal {
        (bool ok, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20Minimal.transfer.selector, to, value)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FAILED");
    }
    function _safeApprove(address token, address spender, uint256 value) internal {
        (bool ok, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20Minimal.approve.selector, spender, value)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "APPROVE_FAILED");
    }
}

pragma solidity ^0.8.20;
contract StandardToken {
    uint8 public constant decimals = 18;
    uint256 public constant FIXED_SUPPLY = 1_000_000_000 * 10 ** 18;
    string public name;
    string public symbol;
    uint256 public totalSupply;
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    constructor(string memory name_, string memory symbol_) {
        name = name_;
        symbol = symbol_;
        _mint(msg.sender, FIXED_SUPPLY);
    }
    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }
    function allowance(address owner, address spender) external view returns (uint256) {
        return _allowances[owner][spender];
    }
    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }
    function approve(address spender, uint256 amount) external returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 currentAllowance = _allowances[from][msg.sender];
        require(currentAllowance >= amount, "ERC20_INSUFFICIENT_ALLOWANCE");
        unchecked {
            _approve(from, msg.sender, currentAllowance - amount);
        }
        _transfer(from, to, amount);
        return true;
    }
    function increaseAllowance(address spender, uint256 addedValue) external returns (bool) {
        _approve(msg.sender, spender, _allowances[msg.sender][spender] + addedValue);
        return true;
    }
    function decreaseAllowance(address spender, uint256 subtractedValue) external returns (bool) {
        uint256 currentAllowance = _allowances[msg.sender][spender];
        require(currentAllowance >= subtractedValue, "ALLOWANCE_BELOW_ZERO");
        unchecked {
            _approve(msg.sender, spender, currentAllowance - subtractedValue);
        }
        return true;
    }
    function _transfer(address from, address to, uint256 amount) internal {
        require(from != address(0), "ERC20_INVALID_SENDER");
        require(to != address(0), "ERC20_INVALID_RECEIVER");
        uint256 fromBalance = _balances[from];
        require(fromBalance >= amount, "ERC20_INSUFFICIENT_BALANCE");
        unchecked {
            _balances[from] = fromBalance - amount;
        }
        _balances[to] += amount;
        emit Transfer(from, to, amount);
    }
    function _approve(address owner, address spender, uint256 amount) internal {
        require(owner != address(0), "ERC20_INVALID_APPROVER");
        require(spender != address(0), "ERC20_INVALID_SPENDER");
        _allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }
    function _mint(address to, uint256 amount) internal {
        require(to != address(0), "ERC20_INVALID_RECEIVER");
        totalSupply += amount;
        _balances[to] += amount;
        emit Transfer(address(0), to, amount);
    }
}
